('beatrice-lorenzi',0,'{"slug":"beatrice-lorenzi","name":"Beatrice Lorenzi","category":"Hosting · Panel","description":"Autrice, presentatrice e volto storico dei principali festival italiani. Unisce preparazione culturale, ritmo e grande padronanza del palco.","meta":"Veneto · target 25–44","image":"assets/beatrice.jpg","activities":["Hosting e conduzione main stage","Moderazione di panel e interviste","Presentazione e giuria cosplay","Talk su fantasy, anime, cinema e cultura pop"],"territories":[{"area":"nord","region":"Veneto"}]}'::jsonb,now()),
('lo-scribacchino',1,'{"slug":"lo-scribacchino","name":"Lo Scribacchino","category":"Fantasy · Divulgazione","description":"Autore e divulgatore fantasy specializzato nell’universo di Harry Potter. Porta sul palco lore, teorie e curiosità con uno stile ironico e accessibile.","meta":"Toscana · target 15–45","image":"assets/scribacchino.jpg","activities":["Panel fantasy e letteratura","Approfondimenti su Harry Potter","Firmacopie e incontri editoriali","Interviste e storytelling live"],"territories":[{"area":"centro","region":"Toscana"}]}'::jsonb,now()),
('cristiana-nerdarte',2,'{"slug":"cristiana-nerdarte","name":"Cristiana Nerdarte","category":"Arte · Mitologia · Hosting","description":"Storica dell’arte, cosplayer e divulgatrice. Collega arte, storia, mitologia e saghe nerd in format interattivi e narrativi.","meta":"Toscana / Lombardia · target 18–50+","image":"assets/cristiana.jpg","activities":["Arte in Tim Burton: dal museo al cinema","Il Medioevo secondo Walt Disney: come i cartoni hanno trasformato l’età di mezzo","Cartoni a regola d’arte: che ci fanno le opere d’arte nei classici Disney?","Revelio: l’Arte in Harry Potter fra location ed easter egg","Fiabe spaventose: il lato dark delle fiabe dai Fratelli Grimm alla Disney","Animali fantastici e dove trovarli: dai miti a Newt Scamander!","Dadi e Quadri: fatti ispirare dall’Arte per giocare a Dungeons and Dragons!","Dal Museo al dungeon: quanto sono cambiati i mostri dal mito a DnD?","Pop Olimpo: come ci è finita l’Antica Grecia in TV?","Medioevo da ridere: gli stereotipi comici dell’età di mezzo nella cultura pop","Storie di Streghe: dal mito alla cultura pop","Nell’antro della strega: storie di oggetti stregati fra cappelli a punta, scope volanti e sfere di cristallo","Storie del Piccolo popolo: da dove nascono elfi, fate e folletti?","Storie di Vampiri: dalla mitologia a Hollywood","All’Arrembaggio: i pirati dalla storia al mondo nerd","Invito a Camelot: il mondo di Artù dal mito alla cultura pop","Invito ad Avalon: le donne del mito arturiano e l’evoluzione dei loro personaggi","Benvenuti all’Inferno! Quanto sono biblicamente accurati Hazbin Hotel, Good Omens e Lucifer?","Alle radici di Arda: storia e mito nell’universo di J.R.R. Tolkien","In una galassia lontana lontana: viaggi nello spazio dal Medioevo a Star Wars","I primi cosplayer erano imperatori romani! Viaggio nella storia del cosplay dall’Antica Roma ai giorni nostri"],"territories":[{"area":"nord","region":"Lombardia"},{"area":"centro","region":"Toscana"}]}'::jsonb,now()),
